PythonC++ <pre><code>"""两个窗口同时显示前/后相机；ESC 或 q 提前退出。

已带低延迟参数：不设的话画面延迟会明显偏大。
"""
import os
import sys
import time

import cv2

from dobot_quad import CameraId, RobotClient

# 必须在创建 VideoCapture 之前设置：OpenCV 只能通过这个环境变量传解码参数
